import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static long[] fact;
    public static void main(String[] args) {
        var sc = new MyScanner();
        var out = new PrintWriter(new BufferedOutputStream(System.out));
        int t = 1;
        while (t-- > 0) {
            int n = sc.nextInt();
            long kk = sc.nextLong();
            fact = new long[n + 1];
            fact[0] = 1L;
            for (int i = 1; i <= n; i++) fact[i] = (fact[i - 1] * i) % MOD;
            if (kk == 0) {
                out.println(fact[n]);
            } else if (kk >= n) {
                out.println(0);
            } else {
                int k = (int) kk;
                long tmp = 0L;
                int sign = 1;
                int l = n - k;
                for (int i = 0; i <= l; i++) {
                    long term = powMod(l - i, n) * comb(l, l - i) % MOD;
                    tmp = (tmp + MOD + (term * sign) % MOD) % MOD;
                    sign = -sign;
                }
                long res = 2L * comb(n, k) % MOD * tmp % MOD;
                out.println(res);
            }
        }
        out.close();
    }
    static long comb(int n, int m) {
        if (m == 0 || m == n) return 1L;
        if (m > n || m < 0) return 0L;
        return fact[n] * powMod((fact[m] * fact[n - m]) % MOD, MOD - 2) % MOD;
    }
    static long powMod(long base, long exp) {
        if (exp == 0) return 1L;
        long half = powMod(base, exp / 2);
        half = (half * half) % MOD;
        if ((exp & 1) == 1) half = (half * base) % MOD;
        return half;
    }
    static class MyScanner {
        BufferedReader br;
        StringTokenizer st;
        MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() {
            String str = "";
            try { str = br.readLine(); } catch (IOException e) { e.printStackTrace(); }
            return str;
        }
    }
}
